readSites.fallback:
1px solid
      var(
        --ds-material-overlay-border,
        color-mix(in srgb, var(--ds-color-border-secondary) 72%, transparent)
      )

var(
      --ds-gradient-surface,
      linear-gradient(
        180deg,
        color-mix(
          in srgb,
          var(--ds-surface-card) 96%,
          var(--ds-color-bg-elevated) 4%
        ),

var(
      --ds-material-overlay-shadow,
      var(
        --ds-elevation-4,
        0 24px 64px
          color-mix(in srgb, var(--ds-color-text-primary) 14%, transparent)
      )
    )

undeclaredReads.fallback:
1px solid
      var(
        --ds-material-overlay-border,
        color-mix(in srgb, var(--ds-color-border-secondary) 72%, transparent)
      )

var(
      --ds-gradient-surface,
      linear-gradient(
        180deg,
        color-mix(
          in srgb,
          var(--ds-surface-card) 96%,
          var(--ds-color-bg-elevated) 4%
        ),
        color-mix(
          in srgb,
          var(--ds-surface-card) 90%,
          var(--ds-color-bg-primary) 10%
        )
      )
    )

var(
      --ds-material-overlay-shadow,
      var(
        --ds-elevation-4,
        0 24px 64px
          color-mix(in srgb, var(--ds-color-text-primary) 14%, transparent)
      )
    )
